if(!exists('simulate_transactions'))library(creditratingsystem)
st_hash<-if(exists('.cr_hash'))get('.cr_hash')else getFromNamespace('.cr_hash','creditratingsystem')
st_fixture<-function(){
 cube<-list(schema_version='1.0',kind='ScenarioCube',axes=list('scenario','time','factor'),scenario_ids=list('s'),time_grid=list(1,2),factor_ids=list('market'),values=list(list(list(1),list(1))),weights=list(1),units=list('relative_index'),origin='2021-01-01',frequency='annual',probability_measure='PHYSICAL',sampling_contract=list(law='FORECAST_CONDITIONAL',conditioning_scope='PIT'))
 calendar<-list(list(start_date='2021-01-01',end_date='2022-01-01',payment_date='2022-01-01',scenario_time=1),list(start_date='2022-01-01',end_date='2023-01-01',payment_date='2023-01-01',scenario_time=2))
 base<-lapply(c(9,10),function(cash)list(base_quantity=1,base_unit_price=cash,base_unit_variable_cost=0,base_fixed_cost=0,volume_multiplier=1,price_multiplier=1,variable_cost_multiplier=1,fixed_cost_multiplier=1,working_capital_revenue_ratio=0,cash_taxes=0,capex=0,asset_disposals=0,other_operating_cash=0))
 asset<-list(asset_id='a',currency='EUR',valuation_date='2021-01-01',initial_value=80,salvage_value=80,initial_age_years=2,economic_life_years=10,depreciation_model='straight_line',idiosyncratic_volatility=0,probability_measure='PHYSICAL',year_basis_days=365)
 policy<-list(policy_id='default-reference',version='1',basis='BASEL_CRE36_REFERENCE',assessment_level='obligor',dscr_threshold=1,ltv_threshold=1,dscr_comparison='lt',ltv_comparison='gt',past_due_days_threshold=90,past_due_comparison='gt',past_due_rule_reference='CRE36.68(2)',materiality_rule_reference='declared',utp_rule_reference='declared',dual_test_as_utp=TRUE,economic_joint_timing='SAME_DATE',default_state='ABSORBING_FIRST_DEFAULT')
 params<-list(currency='EUR',reserve_id='reserve',initial_reserve=1,reserve_targets=list(0,0),loans=list(list(terms=list(facility_id='f',currency='EUR',principal=100,rate_type='fixed',annual_rate=.1,rate_convention='nominal_simple',day_count='ACT/365F',amortization='bullet',maturity_date='2023-01-01'),priority=1,deficit_cost_share=1)),operating_contract=list(contract_id='operations',version='1',currency='EUR',period_unit='year',quantity_unit='units',initial_working_capital=0,include_asset_disposals_in_cfads=FALSE),operating_base=base,operating_bindings=setNames(list(),character()),assets=list(list(parameters=asset,market_binding=list(factor_id='market',unit='relative_index',transform='level'),innovation_channel='asset-z',recovery=list(delay_days=0,realization_fraction=1,cost=0,annual_discount_rate=0))),default_policy=policy,materiality=list(absolute_threshold=1,relative_threshold=.01,comparison='gt_both',continuous_between_grid_dates=TRUE),external_evidence=lapply(c('2021-01-01','2022-01-01','2023-01-01'),function(date)list(scenario_id='s',date=date,facility_id='external',materiality_met=FALSE,material_days_past_due=0,utp_indicators=list())),recovery=list(policy=list(policy_id='recovery',version='1',currency='EUR',allocation='LEGAL_CAP',cost_rule='PROCEEDS_FIRST_EXPLICIT_DEFICIT_SHARES',completion='ULTIMATE_COMPLETE'),reserve_recovery='REMAINING_RESERVE_AT_DEFAULT'),sampling_design='IID_UNWEIGHTED',legal_pooling='FULL_OBLIGOR_CROSS_COLLATERALIZED',arrears_interest='NO_ADDITIONAL_ARREARS_INTEREST',payment_allocation='INTEREST_BEFORE_PRINCIPAL')
 snapshot<-list(snapshot_id='p',version='1',parameters=list(p=params));recipe<-list(transaction_id='t',version='1',subject_id='o',parameter_id='p',calendar=calendar,parameter_hash=st_hash(params),cube_hash=st_hash(cube));innovations<-lapply(c('2022-01-01','2023-01-01'),function(date)list(scenario_id='s',date=date,channel_id='asset-z',value=0))
 list(transaction_recipes=list(recipe),scenario_cube=cube,entity_innovations=innovations,parameter_snapshot=snapshot)
}
st_run<-function(args){for(i in seq_along(args$transaction_recipes)){args$transaction_recipes[[i]]$parameter_hash<-st_hash(args$parameter_snapshot$parameters[[args$transaction_recipes[[i]]$parameter_id]]);args$transaction_recipes[[i]]$cube_hash<-st_hash(args$scenario_cube)};do.call(simulate_transactions,args)$value}
st_error<-function(code,expr){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),e$code==code)}
# Coupon 10 is funded by operating9 + reserve1. Maturity110 consumes cash10:
# actual principal100 remains, collateral80 leaves loss20, not contractual balance0.
a<-st_fixture();r<-st_run(a)$transactions[[1]];p<-r$paths[[1]]
stopifnot(p$default_event$first_default_date=='2023-01-01',p$going_concern_ledger[[1]]$liquidity$closing_reserve==0,p$ead_at_default==100,r$risk$expected_loss==20,r$risk$conditional_mean_lgd==.2,length(r$recovery$claim_results)==1L)
a<-st_fixture();a$parameter_snapshot$parameters$p$operating_base[[2]]$base_unit_price<-60;a$parameter_snapshot$parameters$p$assets[[1]]$parameters$initial_value<-40;a$parameter_snapshot$parameters$p$assets[[1]]$parameters$salvage_value<-40;r<-st_run(a)$transactions[[1]]
stopifnot(r$paths[[1]]$ead_at_default==50,r$risk$expected_loss==10,r$paths[[1]]$going_concern_ledger[[2]]$facilities[[1]]$principal_paid==50)
# Collateral1000 does not veto the independent material >90 days event.
a<-st_fixture();a$parameter_snapshot$parameters$p$initial_reserve<-0;for(i in 1:2)a$parameter_snapshot$parameters$p$operating_base[[i]]$base_unit_price<-0;a$parameter_snapshot$parameters$p$assets[[1]]$parameters$initial_value<-1000;a$parameter_snapshot$parameters$p$assets[[1]]$parameters$salvage_value<-1000;r<-st_run(a)$transactions[[1]]
stopifnot(r$paths[[1]]$default_event$first_default_date=='2023-01-01',identical(r$paths[[1]]$default_event$reasons,list('MATERIAL_PAST_DUE')),r$paths[[1]]$ead_at_default==120,r$risk$pd==1,r$risk$expected_loss==0)
# Initial default never enters initially-performing PD denominator; reserve recovers once.
a<-st_fixture();a$parameter_snapshot$parameters$p$external_evidence[[1]]$utp_indicators<-list('bankruptcy');r<-st_run(a)$transactions[[1]]
stopifnot(r$risk$status=='EMPTY_RISK_SET',length(r$paths[[1]]$going_concern_ledger)==0L,r$recovery$claim_results[[1]]$economic_loss==19,r$recovery$pool_results[[1]]$realized_proceeds==81)
a<-st_fixture();loan<-a$parameter_snapshot$parameters$p$loans[[1]];loan$terms$facility_id<-'f2';loan$priority<-2;loan$deficit_cost_share<-.5;a$parameter_snapshot$parameters$p$loans[[1]]$deficit_cost_share<-.5;a$parameter_snapshot$parameters$p$loans[[2]]<-loan;r<-st_run(a)$transactions[[1]]
stopifnot(r$paths[[1]]$default_event$first_default_date=='2022-01-01',r$paths[[1]]$ead_at_default==210,r$risk$expected_loss==130,sum(vapply(r$paths[[1]]$going_concern_ledger[[1]]$liquidity$payments,function(x)x$payment_from_reserve,0.))==1)
a<-st_fixture();a$parameter_snapshot$parameters$p$operating_base[[2]]$base_unit_price<-120;r<-st_run(a)$transactions[[1]];stopifnot(r$risk$pd==0,r$risk$expected_loss==0,length(r$recovery$claim_results)==0L)
a<-st_fixture();a$parameter_snapshot$parameters$p$initial_reserve<-2;st_error('TRANSACTION_SEAL',do.call(simulate_transactions,a))
a<-st_fixture();recipe<-a$transaction_recipes[[1]];recipe$transaction_id<-'t2';recipe$subject_id<-'o2';recipe$parameter_id<-'p2';p<-a$parameter_snapshot$parameters$p;p$reserve_id<-'reserve2';p$loans[[1]]$terms$facility_id<-'f2';p$assets[[1]]$parameters$asset_id<-'a2';p$operating_contract$contract_id<-'operations2';a$transaction_recipes[[2]]<-recipe;a$parameter_snapshot$parameters$p2<-p;r<-st_run(a);a$transaction_recipes<-rev(a$transaction_recipes);stopifnot(identical(r,st_run(a)));a$parameter_snapshot$parameters$p2$assets[[1]]$parameters$asset_id<-'a';st_error('TRANSACTION_DUPLICATE',st_run(a))
# Tenant receipts were in CFADS: subtract lost receipt once, do not add tenant PD.
a<-st_fixture();dates<-c('2022-01-01','2023-01-01');paths<-lapply(1:2,function(i)list(scenario_id='s',counterparty_id='tenant',period_start=c('2021-01-01','2022-01-01')[i],period_end=dates[i],conditional_pd=c(1,0)[i],innovation_channel='cp-u',probability_measure='PHYSICAL'));contract<-list(contract_id='rent',counterparty_id='tenant',currency='EUR',default_payment_timing='BEFORE_DUE',cure_probability=0,cure_delay_days=0,replacement_enabled=FALSE,replacement_delay_days=0,replacement_payment_fraction=0,cashflows=list(list(date=dates[1],amount=9),list(date=dates[2],amount=10)));a$parameter_snapshot$parameters$p$counterparties<-list(paths=paths,contracts=list(contract),cure_draws=list(list(scenario_id='s',contract_id='rent',innovation_channel='cure-u',innovation_date='2021-01-01')),baseline_receipts='INCLUDED_ONCE_IN_OPERATING_CFADS');a$entity_innovations<-c(a$entity_innovations,lapply(dates,function(d)list(scenario_id='s',date=d,channel_id='cp-u',value=.5)),list(list(scenario_id='s',date='2021-01-01',channel_id='cure-u',value=.5)));r<-st_run(a)$transactions[[1]]
stopifnot(r$paths[[1]]$default_event$first_default_date==dates[1],r$paths[[1]]$going_concern_ledger[[1]]$cfads==0,r$paths[[1]]$ead_at_default==109,r$risk$expected_loss==29,r$risk$pd==1)
a<-st_fixture();a$scenario_cube$frequency<-'monthly';st_error('TRANSACTION_CALENDAR',st_run(a));a<-st_fixture();a$transaction_recipes[[1]]$calendar[[1]]$end_date<-'2021-01-02';a$transaction_recipes[[1]]$calendar[[1]]$payment_date<-'2021-01-02';st_error('TRANSACTION_CALENDAR',st_run(a))
a<-st_fixture();a$entity_innovations[[3]]<-list(scenario_id='s',date='2022-01-01',channel_id='unused',value=0);st_error('TRANSACTION_INNOVATION',st_run(a))
cat('Native transaction hand cash/default/recovery/calendar cases PASS\n')
